// Builds themes/md3e-tokens.css from @materialwebunofficial/md3e-web:
//   - every --md-sys-* token of the package's tokens.css that is not a color
//     (type scale, shape, state, elevation, spacing, expressive motion),
//   - a dark and a light "expressive" color scheme per seed, generated by
//     the package's own engine (Material Color Utilities, 2025 spec),
// all scoped to :root[data-agy-theme="md3e"] so the theme can be swapped.
// Light blocks add [data-agy-mode="light"] (theme-host.js mirrors the app's
// own light/dark setting there) and come after every dark block: in light
// mode the seed's light block (one attribute more) or teal's (later) wins.
//
//   node tools/build-md3e.mjs <path-to-md3e-web-package>
//
// The output is committed; the theme needs no package at runtime.

import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const pkg = process.argv[2];
if (!pkg) throw new Error('usage: node tools/build-md3e.mjs <path-to-md3e-web-package>');
const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '..');
const meta = JSON.parse(readFileSync(path.join(pkg, 'package.json'), 'utf8'));
const { generateM3Scheme } = await import(pathToFileURL(path.join(pkg, 'src/theme/hct-color-engine.js')).href);

// Seeds offered in the Theme menu (key -> source color). Hex values of the
// non-teal seeds are the package's own showcase presets.
const SEEDS = [
  { key: null,     name: 'Teal',   hex: '#006A6A' },
  { key: 'ocean',  name: 'Ocean',  hex: '#00639B' },
  { key: 'forest', name: 'Forest', hex: '#386A20' },
  { key: 'amber',  name: 'Amber',  hex: '#7D5700' },
  { key: 'coral',  name: 'Coral',  hex: '#9C4146' },
];

// 1) Non-color --md-sys-* declarations from the blocks the package applies to
//    a dark, expressive page: :root, [data-theme="dark"], and
//    [data-motion-scheme="expressive"]. Later blocks win, as in the source.
//    Blocks use selector lists (":root, [data-theme-scheme=…], …"): take a
//    block when its list names one of these and never the standard scheme
//    (its block also sets spatial-fast etc. and comes after expressive).
//    @media blocks are dropped: the reduced-motion one zeroes every duration.
const css = readFileSync(path.join(pkg, 'dist', 'tokens.css'), 'utf8')
  .replace(/\/\*[\s\S]*?\*\//g, '')
  .replace(/@media[^{]*\{(?:[^{}]*\{[^{}]*\})*[^{}]*\}/g, '');
const wanted = new Set([':root', '[data-theme="dark"]', '[data-motion-scheme="expressive"]']);
const tokens = new Map();
for (const m of css.matchAll(/([^{}@]+)\{([^{}]*)\}/g)) {
  const selectors = m[1].split(',').map((s) => s.trim());
  if (!selectors.some((s) => wanted.has(s)) || selectors.some((s) => s.includes('standard'))) continue;
  for (const d of m[2].matchAll(/(--md-sys-[\w-]+)\s*:\s*([^;]+);/g)) {
    if (d[1].startsWith('--md-sys-color-')) continue;
    tokens.set(d[1], d[2].trim());
  }
}
// Roboto is registered by theme-host.js from the bundled woff2; fall back to
// the system UI font if it ever fails to load.
tokens.set('--md-sys-typescale-font-family', `'Roboto', 'Segoe UI Variable Text', 'Segoe UI', system-ui, sans-serif`);

// 2) Expressive schemes per seed, dark then light
const scheme = (hex, dark) => Object.entries(generateM3Scheme(hex, dark, 'expressive'))
  .filter(([name]) => name.startsWith('--md-sys-color-'));

const out = [];
out.push(`/* GENERATED by tools/build-md3e.mjs — do not edit.`);
out.push(`   Source: ${meta.name} ${meta.version} (${meta.license}); see vendor/md3e/NOTICE.`);
out.push(`   ${tokens.size} non-color system tokens + dark and light "expressive" schemes (MCU 2025). */`);
out.push(`:root[data-agy-theme="md3e"] {`);
for (const [name, value] of tokens) out.push(`  ${name}: ${value};`);
out.push(`  /* seed: ${SEEDS[0].name} ${SEEDS[0].hex} */`);
for (const [name, value] of scheme(SEEDS[0].hex, true)) out.push(`  ${name}: ${value};`);
out.push(`}`);
for (const seed of SEEDS.slice(1)) {
  out.push(`:root[data-agy-theme="md3e"][data-agy-seed="${seed.key}"] { /* ${seed.name} ${seed.hex} */`);
  for (const [name, value] of scheme(seed.hex, true)) out.push(`  ${name}: ${value};`);
  out.push(`}`);
}
out.push(`/* Light mode */`);
for (const seed of SEEDS) {
  const sel = seed.key ? `[data-agy-seed="${seed.key}"]` : '';
  out.push(`:root[data-agy-theme="md3e"]${sel}[data-agy-mode="light"] { /* ${seed.name} ${seed.hex}, light */`);
  for (const [name, value] of scheme(seed.hex, false)) out.push(`  ${name}: ${value};`);
  out.push(`}`);
}
writeFileSync(path.join(root, 'themes', 'md3e-tokens.css'), out.join('\n') + '\n');

// Swatches for the Theme menu: each seed's generated primary
const swatches = Object.fromEntries(SEEDS.map((s) => [s.key ?? 'teal', generateM3Scheme(s.hex, true, 'expressive')['--md-sys-color-primary']]));
console.log(JSON.stringify({ tokens: tokens.size, seeds: SEEDS.length, swatches }));
